import{u as o,o as r,c as i,j as e,k as s,F as l,a8 as d,e as c,p as u}from"./chunks/framework.fPNBP_58.js";const h=["markdown-url"],p={"data-allow-mismatch":"",style:{display:"none"}},w=JSON.parse('{"title":"Land surface temperatures projections, considering climate and land use changes","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"heatgrid","file":"https://gtif-austria.github.io/public-narratives/heatgrid.md","title":"Land surface temperatures projections, considering climate and land use changes"},"relativePath":"narratives/heatgrid.md","filePath":"narratives/[narrative].md"}'),g={name:"narratives/heatgrid.md"},v=Object.assign(g,{setup(f){const a=u(!0);a.value=!1;const{params:n}=o();return(m,t)=>(r(),i("div",null,[e("client-only",null,[e("eox-storytelling",{"show-nav":"","markdown-url":s(n).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,h)]),e("div",p,[a.value?(r(),i(l,{key:0},[t[0]||(t[0]=d(' --- cover-image: https://raw.githubusercontent.com/gtif-austria/public-narratives/refs/heads/main/assets/gofweiss-source/heatgrid-cover-image.png date: 2026-11-11 theme: Sustainable Cities tags: Land Surface Tempreature, Land Use Change, Climate Change provider: GeoVille --- <h1 id="land-surface-temperatures-projections-considering-climate-and-land-use-changes" tabindex="-1">Land surface temperatures projections, considering climate and land use changes <a class="header-anchor" href="#land-surface-temperatures-projections-considering-climate-and-land-use-changes" aria-label="Permalink to &quot;Land surface temperatures projections, considering climate and land use changes &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/gofweiss-source/Heatgrid/62c9da6f53c7df33ea2f9ed0d9d0a2cd7b10a103/Title_picture_gtif_heatgrid_Vienna.png&quot; }--&gt;&quot;">​</a></h1><h3 id="high-resolution-projections-of-future-land-surface-temperatures-across-urban-areas-in-austria-under-different-climate-scenarios-revealing-the-impact-of-land-use-changes-to-support-the-mitigation-and-adaptation-of-heat-risk-and-identify-the-effects-of-a-potential-urban-growth" tabindex="-1">High-resolution projections of future land surface temperatures across urban areas in Austria under different climate scenarios, revealing the impact of land use changes, to support the mitigation and adaptation of heat risk and identify the effects of a potential urban growth. <a class="header-anchor" href="#high-resolution-projections-of-future-land-surface-temperatures-across-urban-areas-in-austria-under-different-climate-scenarios-revealing-the-impact-of-land-use-changes-to-support-the-mitigation-and-adaptation-of-heat-risk-and-identify-the-effects-of-a-potential-urban-growth" aria-label="Permalink to &quot;High-resolution projections of future land surface temperatures across urban areas in Austria under different climate scenarios, revealing the impact of land use changes, to support the mitigation and adaptation of heat risk and identify the effects of a potential urban growth. &lt;!--{ style=&quot;font-size:1.5rem;opacity:0.7;margin-top:1rem;&quot; }--&gt;&quot;">​</a></h3><h2 id="challenge" tabindex="-1">Challenge <a class="header-anchor" href="#challenge" aria-label="Permalink to &quot;Challenge&quot;">​</a></h2><p>Climate change is causing a significant increase in land surface temperatures in urban areas, concrete, asphalt and built infrastructure trap solar energy, elevating temperatures and leading to the urban heat island effect. This intensifies heat exposure and increases demand for cooling, with implications for public health, infrastructure, and energy systems. At the same time, the growing urban population as well as the expansive demand for areas due to activities and consumption patterns lead to an increasing urban sprawl and soil sealing. One important factor influencing land surface temperature is land use, as this affects energy absorption, storage, and release. Addressing urban heat risks requires mitigation and adaptation strategies that reflect local conditions and consider possible land use changes under a changing climate.</p><p><strong>How will land surface temperatures in Austrian urban areas evolve over the coming decades?</strong></p><p><strong>How could land use changes influence future land surface temperature patterns?</strong></p><h2 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h2><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>This capability provides high-resolution (70 m) projections of land surface temperature (LST), based on the SSP3-7.0 scenario (Shared Socioeconomic Pathway, high-emission future with continuous increases in CO₂ emissions and limited global mitigation efforts) and two models. The capability focuses on the urban areas of Vienna, Graz and Innsbruck in Austria, covering the period from 2000 to 2049 (aggregated in decades) and showing the average minimum and maximum temperatures during hot spells in the morning and afternoon. Furthermore, it examines the relationship between land use and LST to evaluate the potential influence of alternative land use on local surface temperatures. This enables users to explore the temperature effects of land use changes (LUC) under future climate conditions. The resulting maps highlight spatial variations in future LST, aiding the identification of potential hotspots and the assessment of the implications of land use choices. They also facilitate the exploration of targeted measures for urban heat mitigation and adaptation to urban heat risks. <img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/AoI%20Heatgrid.png" alt="Overview map of the areas of interest"><em>Overview map of the areas of interest</em></p><h3 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h3><p><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/Method%20Heatgrid.png" alt="Flowchart of the method"><em>Flowchart of the method</em></p><h3 id="technical-features" tabindex="-1">Technical features <a class="header-anchor" href="#technical-features" aria-label="Permalink to &quot;Technical features&quot;">​</a></h3><h4 id="spatial-resolution" tabindex="-1">Spatial resolution <a class="header-anchor" href="#spatial-resolution" aria-label="Permalink to &quot;Spatial resolution&quot;">​</a></h4><p>70 m grid</p><h4 id="geographical-coverage" tabindex="-1">Geographical coverage <a class="header-anchor" href="#geographical-coverage" aria-label="Permalink to &quot;Geographical coverage&quot;">​</a></h4><ul><li>Urban area | S2-tile | CRS (EPSG) | extent (minx, miny, maxx, maxy) | area</li><li>Graz | 33TWN 32633 | 524970, 5190280, 544920, 5220100 | 595 Km²</li><li>Innsbruck | 32TPT 32632 | 674970, 5230040, 689950, 5245090 | 225 Km²</li><li>Vienna | 33UWP 32633 | 589930, 5330000, 609740, 5355060 | 496 Km²</li></ul><h4 id="time-extension" tabindex="-1">Time extension <a class="header-anchor" href="#time-extension" aria-label="Permalink to &quot;Time extension&quot;">​</a></h4><p>Two times (averaged coldest two morning and three warmest afternoon hours of 4-days-hot-spell per year between 2000 and 2049) averaged per decade (from 2000 to 2009, from 2010 to 2019, from 2020 to 2029, from 2030 to 2039, from 2040 to 2049).</p><h4 id="input-data" tabindex="-1">Input data <a class="header-anchor" href="#input-data" aria-label="Permalink to &quot;Input data&quot;">​</a></h4><ul><li><a href="https://ecostress.jpl.nasa.gov/" target="_blank" rel="noreferrer">ECOSTRESS</a></li><li>reflectance data from <a href="https://dataspace.copernicus.eu/data-collections/copernicus-sentinel-missions/sentinel-2" target="_blank" rel="noreferrer">Sentinel-2</a> (blue, green, red, NIR, SWIR-1, SWIR-2)</li><li>meteorological features from <a href="https://data.hub.geosphere.at/de/dataset/inca-v1-1h-1km" target="_blank" rel="noreferrer">INCA</a> (air temperature at 2m above ground, global radiation, relative humidity at 2m above ground, west-east wind speed, south-north wind speed) to train the 70m LST modeling</li><li>meteorological features from the Climate DT data of <a href="https://platform.destine.eu/" target="_blank" rel="noreferrer">DestinationEarth</a> (air temperature at 2m above ground, global radiation, relative humidity at 2m above ground, west-east wind speed, south-north wind speed) for the two climate scenarios predictions <a href="https://mpimet.mpg.de/forschung/modellierung" target="_blank" rel="noreferrer">ICON</a> (developed by DWD/MPI-M) and <a href="https://www.ecmwf.int/en/elibrary/75709-coupling-nemo-and-ifs-models-single-executable" target="_blank" rel="noreferrer">IFS-NEMO</a> (developed by ECMWF).</li><li>ancillary features (terrain aspect, digital elevation model, imperviousness, terrain slope, tree cover density, water and wetness index)</li><li>LULUCF 10m data from another Geoville’s project <a href="https://ghg-kit.at/" target="_blank" rel="noreferrer">GHG-Kit</a> (see narrative <a href="https://gtif-austria.info/narratives/land_use_land_use_change_and_forestry" target="_blank" rel="noreferrer">GHG-KIT LULUCF Activity Data</a>)</li></ul><h3 id="for-whom-for-what" tabindex="-1">For whom? For what? <a class="header-anchor" href="#for-whom-for-what" aria-label="Permalink to &quot;For whom? For what?&quot;">​</a></h3><h4 id="target-groups" tabindex="-1">Target groups <a class="header-anchor" href="#target-groups" aria-label="Permalink to &quot;Target groups&quot;">​</a></h4><p>The capability can support:</p><ul><li>Municipalities and regional authorities — urban development, spatial planning, and climate adaptation strategies.</li><li>Urban planners, architects, and landscape architects — evaluating the potential thermal implications of development and design choices.</li><li>Real estate developers and property owners — understanding local surface heat patterns and informing site planning.</li><li>Healthcare and care infrastructure, schools, and hospitals — identifying potentially heat-exposed sites and informing adaptation planning.</li><li>Businesses and infrastructure operators — assessing surface heat conditions around facilities and operational sites.</li></ul><h4 id="potential-use-cases" tabindex="-1">Potential use cases <a class="header-anchor" href="#potential-use-cases" aria-label="Permalink to &quot;Potential use cases&quot;">​</a></h4><p>The capability can support planning and assessment related to:</p><ul><li>Urban development and redevelopment — exploring the potential temperature implications of new construction and renovation.</li><li>Heat mitigation and adaptation — identifying potential hotspots and prioritising areas for intervention.</li><li>Greening and de-sealing — assessing the potential surface-temperature benefits of vegetation, permeable surfaces, and other land-use changes.</li><li>Climate-resilient site planning — comparing local temperature patterns to inform the placement and design of buildings, outdoor spaces, and infrastructure.</li><li>Long-term climate adaptation — exploring how urban surface-temperature patterns may evolve under different climate scenarios.</li></ul><h3 id="about-us" tabindex="-1">About us <a class="header-anchor" href="#about-us" aria-label="Permalink to &quot;About us&quot;">​</a></h3><p>Provider: <a href="https://www.geoville.com/" target="_blank" rel="noreferrer">GeoVille</a></p><p><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/logo_GeoVille.png" alt="GeoVille logo"></p><p>Project partners: <a href="https://eox.at/" target="_blank" rel="noreferrer">EOX</a>, <a href="http://www.austriatourism.com/" target="_blank" rel="noreferrer">Austria Tourism</a>, <a href="https://www.brz.gv.at/" target="_blank" rel="noreferrer">Bundesrechenzentrum</a> (BRZ) and <a href="https://www.lfrz.gv.at/" target="_blank" rel="noreferrer">Land-, forst- und wasserwirtschaftliche Rechenzentrum</a> (LFRZ)</p><p><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/logo_EOx.png" alt="EOX logo"><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/logo_AustriaTourism.png" alt="Austria Tourism logo"><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/a056a475ebd99da08bfd75e0aae25a4aabcf7bbd/logo_BRZ.png" alt="Bundesrechenzentrum logo"><img src="https://raw.githubusercontent.com/gofweiss-source/Heatgrid/aa635caafad36feae98946b7f458aaa76c67f99b/logo_LFRZ.jpg" alt="Land-, forst- und wasserwirtschaftliche Rechenzentrum logo"></p>',33))],64)):c("",!0)])]))}});export{w as __pageData,v as default};
